from typing import List


def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play modified tic-tac-toe; both players choose optimally."""
    values = tuple(grid[r][c] for r in range(3) for c in range(3))
    lines = (
        0b000000111, 0b000111000, 0b111000000,
        0b001001001, 0b010010010, 0b100100100,
        0b100010001, 0b001010100,
    )
    winning_masks = tuple(lines)

    @lru_cache(None)
    def solve(red: int, blue: int) -> bool:
        # Return True when optimal play from this position makes Takahashi win.
        occupied = red | blue
        if occupied == 0b111111111:
            red_score = sum(values[i] for i in range(9) if red & (1 << i))
            blue_score = sum(values[i] for i in range(9) if blue & (1 << i))
            return red_score > blue_score

        takahashi_turn = occupied.bit_count() % 2 == 0
        outcomes = []
        for i in range(9):
            bit = 1 << i
            if occupied & bit:
                continue
            if takahashi_turn:
                new_red, new_blue = red | bit, blue
                if any(new_red & mask == mask for mask in winning_masks):
                    result = True
                else:
                    result = solve(new_red, new_blue)
            else:
                new_red, new_blue = red, blue | bit
                if any(new_blue & mask == mask for mask in winning_masks):
                    result = False
                else:
                    result = solve(new_red, new_blue)
            outcomes.append(result)
        return any(outcomes) if takahashi_turn else all(outcomes)

    return "Takahashi" if solve(0, 0) else "Aoki"

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether the Levenshtein distance between s and t is at most k."""
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t:
        return True

    inf = k + 1
    # Keep only the diagonal band that can still reach a result of at most k.
    prev = [inf] * (m + 1)
    for j in range(min(m, k) + 1):
        prev[j] = j

    for i in range(1, n + 1):
        lo = max(1, i - k)
        hi = min(m, i + k)
        curr = [inf] * (m + 1)
        if i <= k:
            curr[0] = i

        row_min = inf
        for j in range(lo, hi + 1):
            cost = 0 if s[i - 1] == t[j - 1] else 1
            value = min(
                prev[j] + 1,       # delete from s
                curr[j - 1] + 1,   # insert into s
                prev[j - 1] + cost,
            )
            curr[j] = value
            if value < row_min:
                row_min = value

        if row_min > k:
            return False
        prev = curr

    return prev[m] <= k

