def can_transform(k: int, s: str, t: str) -> bool:
    """Determine whether s can be transformed into t using at most k edits."""
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False
    if s == t:
        return True

    inf = k + 1
    prev = [inf] * (m + 1)
    curr = [inf] * (m + 1)
    for j in range(min(m, k) + 1):
        prev[j] = j

    for i in range(1, n + 1):
        lo = max(1, i - k)
        hi = min(m, i + k)
        if lo > hi:
            return False
        if lo > 0:
            curr[lo - 1] = inf
        if i <= k:
            curr[0] = i

        row_min = inf
        for j in range(lo, hi + 1):
            cost = 0 if s[i - 1] == t[j - 1] else 1
            value = min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost)
            curr[j] = value
            if value < row_min:
                row_min = value

        if row_min > k:
            return False
        # The cell above the band must not retain a stale value when it becomes
        # part of the previous row's recurrence window.
        if hi < m:
            curr[hi + 1] = inf
        prev, curr = curr, prev

    return prev[m] <= k

