def tic_tac_toe_winner(grid: List[List[int]]) -> str:
    """Play modified tic-tac-toe; both players choose optimally."""
    values = tuple(grid[r][c] for r in range(3) for c in range(3))
    winning_masks = (
        0b000000111, 0b000111000, 0b111000000,
        0b001001001, 0b010010010, 0b100100100,
        0b100010001, 0b001010100,
    )
    win_value = 10**30

    @lru_cache(None)
    def solve(red: int, blue: int) -> int:
        occupied = red | blue
        if occupied == 0b111111111:
            return sum(values[i] if red & (1 << i) else -values[i]
                       for i in range(9))

        takahashi_turn = occupied.bit_count() % 2 == 0
        outcomes = []
        for i in range(9):
            bit = 1 << i
            if occupied & bit:
                continue
            if takahashi_turn:
                new_red, new_blue = red | bit, blue
                if any(new_red & mask == mask for mask in winning_masks):
                    result = win_value
                else:
                    result = values[i] + solve(new_red, new_blue)
            else:
                new_red, new_blue = red, blue | bit
                if any(new_blue & mask == mask for mask in winning_masks):
                    result = -win_value
                else:
                    result = -values[i] + solve(new_red, new_blue)
            outcomes.append(result)
        return max(outcomes) if takahashi_turn else min(outcomes)

    return "Takahashi" if solve(0, 0) > 0 else "Aoki"

