    inf = k + 1
    prev = [inf] * (m + 1)
    curr = [inf] * (m + 1)
    for j in range(min(m, k) + 1):
        prev[j] = j

    for i in range(1, n + 1):
        lo = max(1, i - k)
        hi = min(m, i + k)
        if lo > hi:
            return False
        curr[lo - 1] = inf
        curr[0] = i if i <= k else inf

        row_min = inf
        for j in range(lo, hi + 1):
            cost = 0 if s[i - 1] == t[j - 1] else 1
            value = min(prev[j] + 1, curr[j - 1] + 1, prev[j - 1] + cost)
            curr[j] = value
            if value < row_min:
                row_min = value

        if row_min > k:
            return False
        if hi < m:
            curr[hi + 1] = inf
        prev, curr = curr, prev

    return prev[m] <= k

