from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    if len(tiles) != n:
        return False

    target_area = h * w
    areas = [a * b for a, b in tiles]
    if not any(sum(areas[i] for i in range(n) if mask & (1 << i)) == target_area
               for mask in range(1 << n)):
        return False

    # The board is a bitset. Filling the first uncovered cell at each step
    # removes symmetries in the order in which tiles are placed.
    full = (1 << target_area) - 1
    placements = []
    for a, b in tiles:
        shapes = {(a, b), (b, a)}
        options = []
        for ph, pw in shapes:
            if ph > h or pw > w:
                continue
            for r in range(h - ph + 1):
                for c in range(w - pw + 1):
                    bits = 0
                    for dr in range(ph):
                        bits |= ((1 << pw) - 1) << ((r + dr) * w + c)
                    options.append((r * w + c, bits))
        placements.append(options)

    # Index placements by the first cell they cover. A placement covering
    # the first empty cell may start above or to its left, so test all options
    # whose span includes that cell.
    by_cell = [[[] for _ in range(target_area)] for _ in range(n)]
    for i, options in enumerate(placements):
        for start, bits in options:
            # The first covered cell is the top-left corner of a rectangle.
            # Record all cells in it; candidates are filtered by bit membership.
            for cell in range(start, target_area):
                if bits & (1 << cell):
                    by_cell[i][cell].append(bits)

    from functools import lru_cache

    @lru_cache(None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        empty = full ^ occupied
        first = (empty & -empty).bit_length() - 1
        for i in range(n):
            if not (remaining & (1 << i)):
                continue
            for bits in by_cell[i][first]:
                if not (occupied & bits) and search(occupied | bits, remaining ^ (1 << i)):
                    return True
        return False

    return search(0, (1 << n) - 1)

