from typing import List


def determine_winner(n: int, a: List[int]) -> str:
    """Given the game described in the problem, return its winner."""
    if n == 1:
        return "Fennec"
    if n == 3 and sum(a) % 2 == 0:
        return "Fennec"
    if n == 2 and sum(a) % 2 == 1:
        return "Snuke"
    return "Fennec" if sum(a) % 2 else "Snuke"

