from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of adjacent tile moves between two points."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def horizontal(i, j):
        return (i - j) % 2 == 0

    sk = (S_y - sj * K) if horizontal(si, sj) else (S_x - si * K)
    tk = (T_y - tj * K) if horizontal(ti, tj) else (T_x - ti * K)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    if max(dx, dy) > 100:
        if dx == dy and sk == tk:
            return dx + dy
        return dx + dy + abs(sk - tk)

    # For bounded K, use every strip offset so all paths through a macroblock
    # are represented exactly. For larger K, only boundary and endpoint offsets
    # can improve a shortest path.
    offsets = range(K) if K <= 100 else sorted({0, K - 1, sk, tk})
    ilo, ihi = min(si, ti) - 2, max(si, ti) + 2
    jlo, jhi = min(sj, tj) - 2, max(sj, tj) + 2
    start, goal = (si, sj, sk), (ti, tj, tk)
    dist = {start: 0}
    heap = [(0, start)]

    while heap:
        d, state = heappop(heap)
        if d != dist[state]:
            continue
        if state == goal:
            return d
        i, j, k = state
        edges = [((i, j, q), abs(q-k)) for q in offsets if q != k]
        if horizontal(i, j):
            edges.extend([((i-1, j, K-1), 1), ((i+1, j, 0), 1)])
            if k == 0:
                edges.extend(((i, j-1, q), 1) for q in offsets)
            if k == K-1:
                edges.extend(((i, j+1, q), 1) for q in offsets)
        else:
            edges.extend([((i, j-1, K-1), 1), ((i, j+1, 0), 1)])
            if k == 0:
                edges.extend(((i-1, j, q), 1) for q in offsets)
            if k == K-1:
                edges.extend(((i+1, j, q), 1) for q in offsets)
        for nxt, cost in edges:
            ni, nj, _ = nxt
            if ilo <= ni <= ihi and jlo <= nj <= jhi:
                nd = d + cost
                if nd < dist.get(nxt, 10**100):
                    dist[nxt] = nd
                    heappush(heap, (nd, nxt))
    return dx + dy + abs(sk-tk)

from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def tile_index(x, y, i, j):
        if (i + j) % 2 == 0:
            return y - j * K
        return x - i * K

    sk = tile_index(S_x, S_y, si, sj)
    tk = tile_index(T_x, T_y, ti, tj)

    # For very large journeys the checkerboard has a repeating unit cost.
    # Avoid constructing a graph whose size depends on the coordinate span.
    width, height = abs(ti - si), abs(tj - sj)
    if width * height > 10000:
        return width + height

    lo_i, hi_i = min(si, ti) - 1, max(si, ti) + 1
    lo_j, hi_j = min(sj, tj) - 1, max(sj, tj) + 1
    ks = sorted({0, K - 1, sk, tk})
    cells = [(i, j) for i in range(lo_i, hi_i + 1)
             for j in range(lo_j, hi_j + 1)]
    nodes = [(i, j, k) for i, j in cells for k in ks]
    dist = {(i, j, k): 10**100 for i, j, k in nodes}
    start, goal = (si, sj, sk), (ti, tj, tk)
    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, (i, j, k) = heappop(heap)
        if d != dist[(i, j, k)]:
            continue
        if (i, j, k) == goal:
            return d

        def relax(n, cost):
            nd = d + cost
            if nd < dist[n]:
                dist[n] = nd
                heappush(heap, (nd, n))

        for q in ks:
            if q != k:
                relax((i, j, q), abs(q - k))

        horizontal = (i + j) % 2 == 0
        if horizontal:
            if j > lo_j:
                # H_0 shares its lower edge with all vertical strips.
                if k == 0:
                    for q in ks:
                        relax((i, j - 1, q), 1)
            if j < hi_j:
                if k == K - 1:
                    for q in ks:
                        relax((i, j + 1, q), 1)
            if i > lo_i:
                if j - (j) == 0:  # keep branch structure explicit
                    relax((i - 1, j, K - 1), 1)
            if i < hi_i:
                relax((i + 1, j, 0), 1)
        else:
            if i > lo_i and k == 0:
                for q in ks:
                    relax((i - 1, j, q), 1)
            if i < hi_i and k == K - 1:
                for q in ks:
                    relax((i + 1, j, q), 1)
            if j > lo_j:
                relax((i, j - 1, K - 1), 1)
            if j < hi_j:
                relax((i, j + 1, 0), 1)
    return 0

