from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count lowercase strings of length m by their LCS length with s."""
    mod = 998244353
    full_mask = (1 << n) - 1
    char_masks = [0] * 26
    for i, ch in enumerate(s):
        char_masks[ord(ch) - ord("a")] |= 1 << i

    # A bit at position i marks the increment from LCS length i to i+1
    # in the DP row for the processed target string. This bitset completely
    # determines the row and therefore forms a finite automaton state.
    dp = {0: 1}
    for _ in range(m):
        next_dp = {}
        for state, ways in dp.items():
            for match_mask in char_masks:
                x = state | match_mask
                y = (state << 1) | 1
                updated = x & ~(x - y) & full_mask
                next_dp[updated] = (next_dp.get(updated, 0) + ways) % mod
        dp = next_dp

    result = [0] * (n + 1)
    for state, ways in dp.items():
        result[state.bit_count()] = (result[state.bit_count()] + ways) % mod
    return result

