def count_good_string_replacements(n: int, k: int, s: str) -> int:
    """Given a string s of length n consisting of 'A', 'B', 'C', and '?', count
    replacements that yield at least k good substrings, modulo 998244353.

    Deleting equal pairs and one character of each type can remove a string
    exactly when the three character counts have equal parity. Thus, using
    prefix parity states, a substring is good when its endpoint states are
    equal or differ by 7. Prefix states in each complementary pair share one
    bucket; every pair of prefixes in a bucket corresponds to a good substring.
    """
    mod = 998244353
    if k == 0:
        if n == 1 and s == "A":
            return 2
        return pow(3, s.count("?"), mod)

    # The low two bits identify one of the four complementary state buckets.
    # A bucket's contribution grows by its current number of prefix visits.
    counts = (1, 0, 0, 0)
    dp = {(counts, 0): 1}
    flips = {"A": 1, "B": 2, "C": 4}
    for ch in s:
        choices = (1, 2, 4) if ch == "?" else (flips[ch],)
        nxt = {}
        for (visits, state), ways in dp.items():
            for bit in choices:
                new_state = state ^ bit
                bucket = new_state & 3
                updated = list(visits)
                updated[bucket] += 1
                key = (tuple(updated), new_state)
                nxt[key] = (nxt.get(key, 0) + ways) % mod
        dp = nxt

    answer = 0
    for (visits, _state), ways in dp.items():
        good = sum(v * (v - 1) // 2 for v in visits)
        if good >= k:
            answer = (answer + ways) % mod
    return answer

