MOD = 998244353


def _ntt(a, invert):
    mod = MOD
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    length = 2
    while length <= n:
        root = pow(3, (mod - 1) // length, mod)
        if invert:
            root = pow(root, mod - 2, mod)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            for k in range(start, start + half):
                u = a[k]
                v = a[k + half] * w % mod
                a[k] = (u + v) % mod
                a[k + half] = (u - v) % mod
                w = w * root % mod
        length <<= 1
    if invert:
        inv_n = pow(n, mod - 2, mod)
        for i in range(n):
            a[i] = a[i] * inv_n % mod


def _multiply(p, q):
    if len(p) * len(q) <= 20000:
        out = [0] * (len(p) + len(q) - 1)
        for i, x in enumerate(p):
            if x:
                for j, y in enumerate(q):
                    out[i + j] = (out[i + j] + x * y) % MOD
        return out
    size = 1
    need = len(p) + len(q) - 1
    while size < need:
        size <<= 1
    a = p + [0] * (size - len(p))
    b = q + [0] * (size - len(q))
    _ntt(a, False)
    _ntt(b, False)
    for i in range(size):
        a[i] = a[i] * b[i] % MOD
    _ntt(a, True)
    return a[:need]


def sum_concatenated_permutations(n: int) -> int:
    """Return the sum of concatenated permutations of 1..n modulo 998244353."""
    counts = {}
    sums = {}
    for i in range(1, n + 1):
        d = len(str(i))
        counts[d] = counts.get(d, 0) + 1
        sums[d] = sums.get(d, 0) + i

    fact = [1] * n
    for i in range(1, n):
        fact[i] = fact[i - 1] * i % MOD

    polys = []
    for d, c in counts.items():
        a = pow(10, d, MOD)
        # Coefficients of (1 + a*x)^c.
        poly = [1] * (c + 1)
        for k in range(1, c + 1):
            poly[k] = poly[k - 1] * (c - k + 1) % MOD
            poly[k] = poly[k] * pow(k, MOD - 2, MOD) % MOD * a % MOD
        polys.append(poly)

    # Multiply shortest polynomials first to keep intermediate transforms small.
    polys.sort(key=len)
    full = [1]
    for poly in polys:
        full = _multiply(full, poly)

    answer = 0
    for d, c in counts.items():
        a = pow(10, d, MOD)
        # Divide the full generating polynomial by one (1+a*x) factor.
        excluded = [0] * n
        excluded[0] = full[0]
        for k in range(1, n):
            excluded[k] = (full[k] - a * excluded[k - 1]) % MOD
        weighted = 0
        for k, coefficient in enumerate(excluded):
            weighted = (weighted + coefficient * fact[k] * fact[n - 1 - k]) % MOD
        answer = (answer + (sums[d] % MOD) * weighted) % MOD
    return answer

