                            changes += 1
                        left += d
                        right -= d
                if changes < best:
                    best = changes
            cost[start][start + length] = best

    inf = n * n + 1
    dp = [[inf] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0
