def _ntt(a, invert):
    mod = MOD
    n = len(a)
    j = 0
    for i in range(1, n):
        bit = n >> 1
        while j & bit:
            j ^= bit
            bit >>= 1
        j ^= bit
        if i < j:
            a[i], a[j] = a[j], a[i]
    length = 2
    while length <= n:
        root = pow(3, (mod - 1) // length, mod)
        if invert:
            root = pow(root, mod - 2, mod)
        half = length >> 1
        for start in range(0, n, length):
            w = 1
            for k in range(start, start + half):
                u = a[k]
                v = a[k + half] * w % mod
                a[k] = (u + v) % mod
                a[k + half] = (u - v) % mod
                w = w * root % mod
        length <<= 1
    if invert:
        inv_n = pow(n, mod - 2, mod)
        for i in range(n):
            a[i] = a[i] * inv_n % mod


def _multiply(p, q):
    if len(p) * len(q) <= 20000:
        out = [0] * (len(p) + len(q) - 1)
        for i, x in enumerate(p):
            if x:
                for j, y in enumerate(q):
                    out[i + j] = (out[i + j] + x * y) % MOD
        return out
    size = 1
    need = len(p) + len(q) - 1
    while size < need:
        size <<= 1
    a = p + [0] * (size - len(p))
    b = q + [0] * (size - len(q))
    _ntt(a, False)
    _ntt(b, False)
    for i in range(size):
        a[i] = a[i] * b[i] % MOD
    _ntt(a, True)
    return a[:need]


