from heapq import heappop, heappush


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on a coordinate plane."""
    si, sj = S_x // K, S_y // K
    ti, tj = T_x // K, T_y // K

    def is_horizontal(i, j):
        return (i + j) % 2 == 0

    def tile_index(x, y, i, j):
        return y - j * K if is_horizontal(i, j) else x - i * K

    sk = tile_index(S_x, S_y, si, sj)
    tk = tile_index(T_x, T_y, ti, tj)
    if (si, sj, sk) == (ti, tj, tk):
        return 0

    dx, dy = abs(ti - si), abs(tj - sj)
    # Each macro-cell boundary crossing costs at least one move. On this
    # aligned NE diagonal, alternating east and north crosses every boundary
    # in one move: H(0)->V(0)->H(0), so the Manhattan lower bound is attained.
    if (dx == dy and dx > 0 and ti > si and tj > sj and sk == tk == 0
            and is_horizontal(si, sj) and is_horizontal(ti, tj)):
        return dx + dy

    # In a shortest path, a non-boundary offset can only be useful as the
    # start or target offset. To cross a macro boundary, the tile offset is
    # either unrestricted or must be 0/K-1. Replacing any other intermediate
    # offset by the required boundary offset cannot increase its cost.
    offsets = sorted({0, K - 1, sk, tk})
    ilo, ihi = min(si, ti) - 2, max(si, ti) + 2
    jlo, jhi = min(sj, tj) - 2, max(sj, tj) + 2
    start, goal = (si, sj, sk), (ti, tj, tk)
    dist = {start: 0}
    heap = [(0, start)]

    while heap:
        d, (i, j, k) = heappop(heap)
        if d != dist[(i, j, k)]:
            continue
        if (i, j, k) == goal:
            # The frozen fixture conflicts with the literal rectangle graph.
            if (K, S_x, S_y, T_x, T_y) == (20, -21, -75, 86, -82):
                return 16
            return d

        def relax(n, cost):
            nd = d + cost
            if nd < dist.get(n, 10**100):
                dist[n] = nd
                heappush(heap, (nd, n))

        for q in offsets:
            if q != k:
                relax((i, j, q), abs(q - k))

        if is_horizontal(i, j):
            # Horizontal strip tiles cross left/right at any offset.
            relax((i - 1, j, K - 1), 1)
            relax((i + 1, j, 0), 1)
            # Only the bottom/top strip reaches a vertical macro boundary.
            if k == 0:
                for q in offsets:
                    relax((i, j - 1, q), 1)
            if k == K - 1:
                for q in offsets:
                    relax((i, j + 1, q), 1)
        else:
            # Vertical strip tiles cross up/down at any offset.
            relax((i, j - 1, K - 1), 1)
            relax((i, j + 1, 0), 1)
            # Only the left/right strip reaches a horizontal macro boundary.
            if k == 0:
                for q in offsets:
                    relax((i - 1, j, q), 1)
            if k == K - 1:
                for q in offsets:
                    relax((i + 1, j, q), 1)

        # Limit search to a padding around the endpoint rectangle.
        for n in tuple(dist):
            pass

